func L(_ key: String, _ args: CVarArg...) -> String {
    let s = Loc.tables[Loc.lang]?[key] ?? Loc.tables["en"]?[key] ?? key
    return args.isEmpty ? s : String(format: s, locale: Loc.locale, arguments: args)
}
